// assetFor renders a card. A missing or invalid entry is a content bug, so it
// is logged and rendered visibly instead of silently disappearing.
func assetFor(c ssg.Ctx, id string, showLicense bool) templpkg.Component {
	asset, ok := assetLibrary.Get(id)
	if !ok {
		log.Printf("asset %q not found in any meta.json", id)
		return assetMissing(id, "not found")
	}
	if asset.Type != "image" && asset.Type != "video" && asset.Type != "audio" {
		log.Printf("asset %q has unsupported type %q", id, asset.Type)
		return assetMissing(id, "unsupported type: "+asset.Type)
	}
	return assetCard(c, asset, showLicense)
}

